def validate_name_length_min(value):
    if len(value) < 2:
        return "name must be at least 2 characters"


def validate_name_length_max(value):
    if len(value) > 100:
        return "name must be at most 100 characters"


def validate_email_contains_at(value):
    if "@" not in value:
        return "email must contain @"


def validate_email_length(value):
    if len(value) > 254:
        return "email is too long"


def validate_age_integer(value):
    if not isinstance(value, int):
        return "age must be an integer"


def validate_age_range(value):
    if isinstance(value, int) and not (0 <= value <= 150):
        return "age must be between 0 and 150"


def validate_role(value):
    if value not in ("admin", "user", "moderator"):
        return "role must be admin, user, or moderator"


FIELD_VALIDATORS = {
    "name": [validate_name_length_min, validate_name_length_max],
    "email": [validate_email_contains_at, validate_email_length],
    "age": [validate_age_integer, validate_age_range],
    "role": [validate_role],
}


def validate_user_input(data):
    errors = []

    for field, validators in FIELD_VALIDATORS.items():
        if field not in data:
            errors.append(f"{field} is required")
            continue

        for validator in validators:
            error = validator(data[field])
            if error:
                errors.append(error)

    return errors
